- const entry="
 import{DurableObject}from'cloudflare:workers';
 import*as workflowGate from'./lib/mcp-fixed-terminal-workflows.mjs';
 import*as activationWire from'./lib/mcp-qa-finite-initial-activation-wire.mjs';
 import{readPrivateQaFiniteCandidate}from'./lib/mcp-qa-finite-candidate-residency.mjs';
 import{observeFiniteOwnerStageWork}from'./lib/mcp-qa-finite-stage-work.mjs';
