 const P='afw.finite-initial-cleanup.v1:';
 const KEY='afw.finite-initial-preparation.v1:entry';
 export class Node extends DurableObject{}
 export class Initial extends FiniteClosure{
 async seed(rows){for(const[k,v]of rows)await this.ctx.storage.put(k,v);await this.ctx.storage.sync();}
